const body = $input.first().json.body || {};

const operation = body.operation || 'search';
const query = body.query;
const url = body.url;
const product = body.product;
const language = body.language;
const max_results = body.max_results || 5;

// Validation
const errors = [];

const validOps = ['search', 'fetch', 'code_samples'];
if (!validOps.includes(operation)) {
  errors.push(`operation invalide: ${operation}. Valeurs: ${validOps.join(', ')}`);
}

if (operation === 'search' && !query) {
  errors.push('query requis pour operation search');
}
if (operation === 'fetch' && !url) {
  errors.push('url requis pour operation fetch');
}
if (operation === 'code_samples' && !query) {
  errors.push('query requis pour operation code_samples');
}

if (errors.length > 0) {
  return {
    json: {
      valid: false,
      error: { code: 400, message: errors.join(', '), status: 'BAD_REQUEST' }
    }
  };
}

return {
  json: {
    valid: true,
    operation,
    query,
    url,
    product,
    language,
    max_results
  }
};

const response = $input.first().json;
const input = $('Validate Input').first().json;

// Extract session ID from headers
const headers = response.headers || {};
const sessionId = headers['mcp-session-id'] || headers['Mcp-Session-Id'];

// Parse response body (may be SSE format)
let initResult;
const body = response.body;

try {
  if (typeof body === 'string') {
    // Handle SSE format: data: {...}
    if (body.includes('data:')) {
      const lines = body.split('\n');
      for (const line of lines) {
        if (line.startsWith('data:')) {
          const jsonStr = line.substring(5).trim();
          if (jsonStr) {
            initResult = JSON.parse(jsonStr);
            break;
          }
        }
      }
    } else {
      initResult = JSON.parse(body);
    }
  } else {
    initResult = body;
  }
} catch (e) {
  return {
    json: {
      error: true,
      message: 'Failed to parse init response',
      raw: body
    }
  };
}

// Check for initialization error
if (initResult?.error) {
  return {
    json: {
      error: true,
      message: initResult.error.message || 'Init failed',
      details: initResult.error
    }
  };
}

return {
  json: {
    error: false,
    sessionId,
    serverInfo: initResult?.result?.serverInfo,
    capabilities: initResult?.result?.capabilities,
    operation: input.operation,
    query: input.query,
    url: input.url,
    product: input.product,
    language: input.language,
    max_results: input.max_results
  }
};

const initData = $('Parse Init Response').first().json;
const operation = initData.operation;

// Build tool name and arguments
let toolName, toolArgs;

switch (operation) {
  case 'search':
    toolName = 'microsoft_docs_search';
    toolArgs = { query: initData.query };
    if (initData.product) toolArgs.product = initData.product;
    if (initData.max_results) toolArgs.top = initData.max_results;
    break;

  case 'fetch':
    toolName = 'microsoft_docs_fetch';
    toolArgs = { url: initData.url };
    break;

  case 'code_samples':
    toolName = 'microsoft_code_sample_search';
    toolArgs = { query: initData.query };
    if (initData.language) toolArgs.language = initData.language;
    if (initData.max_results) toolArgs.top = initData.max_results;
    break;
}

return {
  json: {
    sessionId: initData.sessionId,
    operation,
    toolName,
    toolArgs
  }
};

const prepData = $('Prepare Tool Call').first().json;
const response = $input.first().json;

const statusCode = response.statusCode || 200;
const body = response.body;

// Handle HTTP errors
if (statusCode >= 400) {
  return {
    json: {
      success: false,
      error: {
        code: statusCode,
        message: `MCP Server error: ${statusCode}`,
        details: body
      }
    }
  };
}

// Parse response (may be SSE format)
let result;
try {
  if (typeof body === 'string') {
    // Handle SSE format
    if (body.includes('data:')) {
      const lines = body.split('\n');
      for (const line of lines) {
        if (line.startsWith('data:')) {
          const jsonStr = line.substring(5).trim();
          if (jsonStr && jsonStr !== '[DONE]') {
            try {
              const parsed = JSON.parse(jsonStr);
              // Look for the actual result (has 'result' field)
              if (parsed.result) {
                result = parsed;
              }
            } catch {}
          }
        }
      }
    } else {
      result = JSON.parse(body);
    }
  } else {
    result = body;
  }
} catch (e) {
  return {
    json: {
      success: false,
      error: {
        code: 500,
        message: 'Failed to parse MCP response',
        raw: body?.substring?.(0, 1000) || body
      }
    }
  };
}

// Check for JSON-RPC error
if (result?.error) {
  return {
    json: {
      success: false,
      error: {
        code: result.error.code || 500,
        message: result.error.message || 'MCP error',
        details: result.error.data
      }
    }
  };
}

// Extract tool result content
const toolResult = result?.result;
let content = null;

if (toolResult?.content) {
  // MCP tools return content as array of {type, text} objects
  if (Array.isArray(toolResult.content)) {
    content = toolResult.content.map(c => {
      if (c.type === 'text') {
        // Try to parse as JSON if it looks like JSON
        try {
          return JSON.parse(c.text);
        } catch {
          return c.text;
        }
      }
      return c;
    });
    // If single item, unwrap
    if (content.length === 1) content = content[0];
  } else {
    content = toolResult.content;
  }
}

// Format based on operation
const operation = prepData.operation;
let formattedResult;

switch (operation) {
  case 'search':
    formattedResult = {
      operation: 'search',
      query: prepData.toolArgs.query,
      results: content
    };
    break;

  case 'fetch':
    formattedResult = {
      operation: 'fetch',
      url: prepData.toolArgs.url,
      content: content
    };
    break;

  case 'code_samples':
    formattedResult = {
      operation: 'code_samples',
      query: prepData.toolArgs.query,
      samples: content
    };
    break;

  default:
    formattedResult = { raw: content };
}

return {
  json: {
    success: true,
    ...formattedResult
  }
};

